SELECT carrier, YEAR(delivered_date) AS delivered_year, ROUND((100 * SUM(CASE WHEN status = 'LOST' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lost FROM shipments WHERE shipped_date BETWEEN '2023-12-25' AND '2024-10-01' AND delivered_date BETWEEN '2023-09-01' AND '2024-02-01' AND status IN ('IN_TRANSIT', 'LOST') GROUP BY carrier, delivered_year ORDER BY delivered_year DESC, pct_lost DESC;
